//! 🛂️ Explicit neutral test caller admission keeps one original observer and recipient throughout real runtime calls.
use semio_framework_value::{NativeEncodeControl,native_encoding::{NativeEncodeRetirementRecipient},RetainedCloneGrant};
use semio_framework_os_kernel::os_vcs::io::binary::entity_identity::control::{EntityIdentityAuthority,Observer};
fn policy()->serde_json::Value{serde_json::from_str(include_str!("../../🧫️fixtures/🛂️receiving/🔣️.json")).unwrap()}
pub(crate) fn original<'a>(observer:&'a mut Observer<'a>,recipient:&'a mut NativeEncodeRetirementRecipient)->EntityIdentityAuthority<'a>{let law=policy();let receipt=NativeEncodeControl::new(law["maximumNativeBytes"].as_u64().unwrap()as usize,observer).pause().unwrap();let receipt=receipt.with_retirement_recipient(recipient).unwrap_or_else(|_|panic!("original test recipient is not empty"));EntityIdentityAuthority::resume_retirement(receipt,observer)}
pub(crate) fn close(identity:&mut EntityIdentityAuthority<'_>){let law=policy();let grant=&law["grant"];let grant=RetainedCloneGrant{maximum_items:grant["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:grant["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:grant["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:grant["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:grant["maximumDepth"].as_u64().unwrap()as usize};let maximum=law["maximumCloseTurns"].as_u64().unwrap();identity.encode(|control|{let mut turns=0;while control.has_retirement_owner(){let step=control.close_retirement_recipient(grant)?;assert!(step.progress().fits(grant));turns+=1;assert!(turns<=maximum,"original test retirement remains pending");}Ok::<_,semio_framework_value::ValueError>(())}).unwrap();}
